"""Read a trusted *names-only* native profile view generated by systemd.

The app has no persistent profile database. The source of truth remains
/etc/wireguard/*.conf and this snapshot is refreshed on directory changes.
"""
from __future__ import annotations

import os
import stat
from pathlib import Path

from .discovery import valid_interface

SYSTEM_NAMES = Path("/run/wg-deck-profiles.list")
MAX_BYTES = 4096


def read_native_names(path: Path = SYSTEM_NAMES) -> tuple[str, ...] | None:
    try:
        fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | getattr(os, "O_NOFOLLOW", 0))
    except OSError:
        return None
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or (info.st_mode & 0o022):
            return None
        if info.st_size > MAX_BYTES:
            return None
        with os.fdopen(fd, "rb", closefd=False) as stream:
            raw = stream.read(MAX_BYTES + 1)
        if len(raw) > MAX_BYTES:
            return None
        text = raw.decode("ascii")
    except (OSError, UnicodeError):
        return None
    finally:
        os.close(fd)
    entries = text.splitlines()
    if any(not valid_interface(name) for name in entries):
        return None
    return tuple(sorted(set(entries), key=str.casefold))
